#define RFX_RAW "Data/GEN_RFX_raw.csv"
#define RFX_MARK "Data/GEN_RFX_exit_marker.txt"
#define RFX_NBARS 3000

static int rfx_n = 0;
static int rfx_done = 0;
static int rfx_hdr = 0;
static int rfx_rows = 0;
static int rfx_sgn = 1;	// alt input sign, flipped once per fed bar (reset at INITRUN)

// INFO variant (not a control, not in [detect]; D1 rule 3): the article as PRINTED, 1.414 and 3.14159 built from integers at run time (1414/1000, 314159/100000, gotchas 9d.1 / 9d.8) in the exponent; the cosine's 180 degrees is the PI macro (Zorro float32 PI, as the other variants). Everything else as [corrected_code]. L = 20. Reported, never PASS/FAIL.
var rfx_ncl(vars Price, int Length, var* pSum, var* pMS)
{
	var ncl_f = 1414;
	ncl_f = ncl_f / 1000;
	var ncl_g = 314159;
	ncl_g = ncl_g / 100000;
	var ncl_half = Length;
	ncl_half = ncl_half / 2;
	var ncl_a1 = exp(-ncl_f * ncl_g / ncl_half);
	var ncl_b1 = 2.0 * ncl_a1 * cos(ncl_f * PI / ncl_half);
	var ncl_c2 = ncl_b1;
	var ncl_c3 = -ncl_a1 * ncl_a1;
	var ncl_c1 = 1.0 - ncl_c2 - ncl_c3;
	var ncl_w1 = 4;
	ncl_w1 = ncl_w1 / 100;
	var ncl_w2 = 96;
	ncl_w2 = ncl_w2 / 100;
	vars ncl_Filt = series(Price[0], Length + 2);
	vars ncl_MS = series(0, 2);
	ncl_Filt[0] = ncl_c1 * (Price[0] + Price[1]) / 2.0 + ncl_c2 * ncl_Filt[1] + ncl_c3 * ncl_Filt[2];
	var ncl_Slope = (ncl_Filt[Length] - ncl_Filt[0]) / Length;
	var ncl_Sum = 0;
	int ncl_i;
	for(ncl_i = 1; ncl_i <= Length; ncl_i++)
		ncl_Sum += (ncl_Filt[0] + ncl_i * ncl_Slope) - ncl_Filt[ncl_i];
	ncl_Sum = ncl_Sum / Length;
	ncl_MS[0] = ncl_w1 * ncl_Sum * ncl_Sum + ncl_w2 * ncl_MS[1];
	var ncl_R = 0;
	if(ncl_MS[0] > 0)
		ncl_R = ncl_Sum / sqrt(ncl_MS[0]);
	*pSum = ncl_Sum;
	*pMS = ncl_MS[0];
	return ncl_R;
}

// NCA: realistic copying error in the pole factor (D2 rule 4). [corrected_code] except a1 + 1/1000 (1/1000 built from a variable, 9d.8) BEFORE b1, c3 and c1 are derived. L = 20.
var rfx_nca(vars Price, int Length, var* pSum, var* pMS)
{
	var nca_k = sqrt(2.0);
	var nca_half = Length;
	nca_half = nca_half / 2;
	var nca_a1 = exp(-nca_k * PI / nca_half);
	var nca_e = 1;
	nca_e = nca_e / 1000;
	nca_a1 = nca_a1 + nca_e;
	var nca_b1 = 2.0 * nca_a1 * cos(nca_k * PI / nca_half);
	var nca_c2 = nca_b1;
	var nca_c3 = -nca_a1 * nca_a1;
	var nca_c1 = 1.0 - nca_c2 - nca_c3;
	var nca_w1 = 4;
	nca_w1 = nca_w1 / 100;
	var nca_w2 = 96;
	nca_w2 = nca_w2 / 100;
	vars nca_Filt = series(Price[0], Length + 2);
	vars nca_MS = series(0, 2);
	nca_Filt[0] = nca_c1 * (Price[0] + Price[1]) / 2.0 + nca_c2 * nca_Filt[1] + nca_c3 * nca_Filt[2];
	var nca_Slope = (nca_Filt[Length] - nca_Filt[0]) / Length;
	var nca_Sum = 0;
	int nca_i;
	for(nca_i = 1; nca_i <= Length; nca_i++)
		nca_Sum += (nca_Filt[0] + nca_i * nca_Slope) - nca_Filt[nca_i];
	nca_Sum = nca_Sum / Length;
	nca_MS[0] = nca_w1 * nca_Sum * nca_Sum + nca_w2 * nca_MS[1];
	var nca_R = 0;
	if(nca_MS[0] > 0)
		nca_R = nca_Sum / sqrt(nca_MS[0]);
	*pSum = nca_Sum;
	*pMS = nca_MS[0];
	return nca_R;
}

