	Y[52] = rfx_o_ms;
	Y[56] = ReflexCore(S0, 20, &rfx_o_sum, &rfx_o_ms);	// L20 flat
	Y[54] = rfx_o_sum;
	Y[55] = rfx_o_ms;
	Y[59] = ReflexCore(S1, 20, &rfx_o_sum, &rfx_o_ms);	// L20 s5
	Y[57] = rfx_o_sum;
	Y[58] = rfx_o_ms;
	Y[62] = ReflexCore(S2, 20, &rfx_o_sum, &rfx_o_ms);	// L20 s10
	Y[60] = rfx_o_sum;
	Y[61] = rfx_o_ms;
	Y[65] = ReflexCore(S3, 20, &rfx_o_sum, &rfx_o_ms);	// L20 s20
	Y[63] = rfx_o_sum;
	Y[64] = rfx_o_ms;
	Y[68] = ReflexCore(S4, 20, &rfx_o_sum, &rfx_o_ms);	// L20 s40
	Y[66] = rfx_o_sum;
	Y[67] = rfx_o_ms;
	Y[71] = ReflexCore(S5, 20, &rfx_o_sum, &rfx_o_ms);	// L20 s100
